import{_ as i,l as d,o as e,c as l,v as r,p as s,x as t,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"分布式死锁","description":"","frontmatter":{"title":"分布式死锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-deadlock.md","filePath":"cs/distributed-deadlock.md","lastUpdated":1789023840000}'),E={name:"cs/distributed-deadlock.md"};function h(_,a,u,m,B,b){const o=d("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="分布式死锁" tabindex="-1">分布式死锁 <a class="header-anchor" href="#分布式死锁" aria-label="Permalink to &quot;分布式死锁&quot;">​</a></h1><div class="epigraph"><p>等待边跨节点时，局部无环仍可能全局有环。检测靠探测或超时，预防靠全局戳与锁序。</p><footer>—— 据 Obermarck 探测算法；Gray and Reuter；单机 wait-for 课的网络扩展</footer></div><p><a href="/cs/spanner-truetime">上一课</a>跨 Paxos 组 2PC。本课不 commit wait。缺口是锁等待图跨机器：片 A 上 T1 等 T2，片 B 上 T2 等 T1，各节点 DFS 看不见环。主干单库 WFG。进阶：边追逐（probe）、中心检测器、或超时。Calvin 定序加锁按键序可避免环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>探测：等待者发 probe 沿等待边走，带着事务 id 路径，回到自己则环。虚假探测、探测风暴是代价。中心：各节点汇报边，中心求环——单点与延迟。超时：假阳性。缺口是<strong>与 2PC 嵌套</strong>：prepared 等协调器，协调器等锁，图更怪，要包含协议边。</p><p>wait-die 用全局时间戳预防，跨节点仍成立若戳全局。伤口等待同理。</p><p><span class="marginnote">Obermarck 分布式死锁检测。Gray and Reuter。本课不实现完整 probe 包格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程常超时+死锁日志，精确检测留给锁量小的系统。Spanner 类：锁在组长，跨组 2PC 超时。Percolator：锁在行上，客户端轮询超时清理。</p><p>锁序：对分片 id 排序加锁，预防环，可能增加延迟（多一轮）。</p>',10)),(e(),s(c,null,{default:t(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22T1%20%E5%9C%A8%E7%89%87%20A%20%E7%AD%89%20T2%22%5D%20--%3E%20PR%5B%22probe%20%E6%B2%BF%E8%BE%B9%22%5D%0A%20%20T2%5B%22T2%20%E5%9C%A8%E7%89%87%20B%20%E7%AD%89%20T1%22%5D%20--%3E%20PR%0A%20%20PR%20--%3E%20CY%5B%22%E5%9B%9E%E5%88%B0%E8%B5%B7%E7%82%B9%E5%88%99%E6%AD%BB%E9%94%81%22%5D%0A%20%20ALT%5B%22%E8%B6%85%E6%97%B6%20%2F%20%E5%85%A8%E5%B1%80%E6%88%B3%E9%A2%84%E9%98%B2%22%5D%20--%3E%20AB%5B%22abort%20%E4%B8%80%E4%BE%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>牺牲者回滚要跨片 undo，2PC abort。检测延迟加大锁持有，放大死锁概率——恶性循环，故预防或短超时常见。</p><p>与 MVCC：无锁等待则无这类环，abort 来自冲突。混合系统两套。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲一致性哈希环。也不把死锁当拜占庭。网络分区造成的「永远等」是故障检测器，不是环。</p><p>后课默认：跨片锁要超时或探测或全局序。一致性哈希在数据库：环上放片，减再平衡搬家。</p><p>分布式 WFG 的边是 RPC，延迟让检测本身过期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全局环需探测、中心图或超时；预防用全局戳或锁序。</li><li>2PC prepared 状态必须进等待模型。</li><li>一致性哈希在数据库下一课。</li><li>出处：Obermarck；Gray and Reuter；wait-die。</li></ul>',9))])}const P=i(E,[["render",h]]);export{A as __pageData,P as default};
